function trieHas(words, query) {
  const root = { children: Object.create(null), terminal: false };
  for (const w of words) {
    let node = root;
    for (const ch of w) {
      if (!node.children[ch]) node.children[ch] = { children: Object.create(null), terminal: false };
      node = node.children[ch];
    }
    node.terminal = true;
  }
  let node = root;
  for (const ch of query) {
    node = node.children[ch];
    if (!node) return false;
  }
  return node.terminal;
}

