function makeSets(n) {
  return { parent: Array.from({ length: n }, (_, i) => i),
           rank: new Array(n).fill(0) };
}

function find(ds, x) {
  while (ds.parent[x] !== x) {
    ds.parent[x] = ds.parent[ds.parent[x]];   // path halving
    x = ds.parent[x];
  }
  return x;
}

function union(ds, a, b) {
  const ra = find(ds, a), rb = find(ds, b);
  if (ra === rb) return false;                // already together
  if (ds.rank[ra] < ds.rank[rb]) { ds.parent[ra] = rb; return true; }
  if (ds.rank[rb] < ds.rank[ra]) { ds.parent[rb] = ra; return true; }
  ds.parent[rb] = ra;
  ds.rank[ra]++;                              // equal heights: one grows
  return true;
}

