function countComponents(n, edges) {
  const ds = makeSets(n);
  let components = n;
  for (const [a, b] of edges) {
    if (union(ds, a, b)) components--;   // only a real merge counts
  }
  return components;
}

function hasCycle(n, edges) {
  const ds = makeSets(n);
  for (const [a, b] of edges) {
    if (!union(ds, a, b)) return true;   // already connected: this edge closes a cycle
  }
  return false;
}

