function countPrefixNodes(words) {
  const root = { children: Object.create(null) };
  let count = 0;
  for (const w of words) {
    let node = root;
    for (const ch of w) {
      if (!node.children[ch]) {
        node.children[ch] = { children: Object.create(null) };
        count++;
      }
      node = node.children[ch];
    }
  }
  return count;
}

