function longestCommonPrefix(words) {
  if (words.length === 0) return '';
  const make = () => ({ children: Object.create(null), terminal: false });
  const root = make();
  for (const w of words) {
    let node = root;
    for (const ch of w) {
      if (!node.children[ch]) node.children[ch] = make();
      node = node.children[ch];
    }
    node.terminal = true;
  }
  let node = root, out = '';
  for (;;) {
    const keys = Object.keys(node.children);
    if (keys.length !== 1 || node.terminal) return out;
    out += keys[0];
    node = node.children[keys[0]];
  }
}

