function unionFindOps(n, ops) {
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };
  const out = [];
  for (const op of ops) {
    const parts = op.split(' ');
    const a = Number(parts[1]), b = Number(parts[2]);
    const ra = find(a), rb = find(b);
    if (parts[0] === 'union') {
      if (ra !== rb) parent[rb] = ra;
    } else {
      out.push(ra === rb);
    }
  }
  return out;
}

