exam.solution:
function wordBreakable(dict, text) {
  if (text.length === 0) return false;
  const make = () => ({ children: Object.create(null), terminal: false });
  const root = make();
  for (const w of dict) {
    let node = root;
    for (const ch of w) {
      if (!node.children[ch]) node.children[ch] = make();
      node = node.children[ch];
    }
    node.terminal = true;
  }
  const memo = new Array(text.length + 1).fill(null);
  const from = (i) => {
    if (i === text.length) return true;
    if (memo[i] !== null) return memo[i];
    let node = root;
    memo[i] = false;
    for (let j = i; j < text.length; j++) {
      node = node.children[text[j]];
      if (!node) break;
      if (node.terminal && from(j + 1)) { memo[i] = true; break; }
    }
    return memo[i];
  };
  return from(0);
}
